import { test, expect } from '@playwright/test';

test.describe('Notification Bell Badge Count', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
    await page.waitForLoadState('networkidle');
  });

  test('should display badge count on notification bell icon', async ({ page }) => {
    const notificationBell = page.getByRole('button', { name: /notifications?/i });

    await expect(notificationBell).toBeVisible();

    const badge = notificationBell.locator('[data-testid="notification-badge"]');
    await expect(badge).toBeVisible();

    const badgeText = await badge.textContent();
    expect(badgeText).toBeTruthy();
    expect(/^\d+$/.test(badgeText || '')).toBeTruthy();
  });

  test('should update badge count when new notification arrives', async ({ page }) => {
    const notificationBell = page.getByRole('button', { name: /notifications?/i });
    const badge = notificationBell.locator('[data-testid="notification-badge"]');

    const initialCount = await badge.textContent();
    expect(initialCount).toBeTruthy();

    await page.evaluate(() => {
      const event = new CustomEvent('notification:new', { detail: { count: parseInt(initialCount || '0') + 1 } });
      window.dispatchEvent(event);
    });

    await page.waitForTimeout(500);

    const updatedCount = await badge.textContent();
    expect(updatedCount).not.toBe(initialCount);
    expect(parseInt(updatedCount || '0')).toBeGreaterThan(parseInt(initialCount || '0'));
  });

  test('should hide badge when notification count is zero', async ({ page }) => {
    const notificationBell = page.getByRole('button', { name: /notifications?/i });
    const badge = notificationBell.locator('[data-testid="notification-badge"]');

    await page.evaluate(() => {
      const event = new CustomEvent('notification:clear-all');
      window.dispatchEvent(event);
    });

    await page.waitForTimeout(500);

    await expect(badge).not.toBeVisible();
  });

  test('should display correct badge styling', async ({ page }) => {
    const notificationBell = page.getByRole('button', { name: /notifications?/i });
    const badge = notificationBell.locator('[data-testid="notification-badge"]');

    await expect(badge).toHaveClass(/badge/);

    const backgroundColor = await badge.evaluate((el) => {
      return window.getComputedStyle(el).backgroundColor;
    });

    expect(backgroundColor).toBeTruthy();
  });
});
